def order_total(items: list, shipping: float, coupon: dict = None) -> float:
    subtotal = sum(i['price'] * i['qty'] for i in items)
    if coupon and coupon['kind'] == 'percent':
        subtotal = subtotal * (100 - coupon['value']) / 100
    elif coupon and coupon['kind'] == 'fixed':
        subtotal = max(0, subtotal - coupon['value'])
    free = subtotal >= 75
    return round(subtotal + (0 if free else shipping), 2)
